<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { listCanteens, saveCanteen } from '../../api/admin'
import type { Canteen } from '../../api/types'
const rows = ref<Canteen[]>([]); const statusFilter = ref<number>(); const filteredRows = computed(() => statusFilter.value === undefined ? rows.value : rows.value.filter(r => r.status === statusFilter.value)); const dialog = ref(false); const form = reactive({ id: undefined as number | undefined, name: '', address: '', status: 1, sort: 0, openTime: '06:30', closeTime: '20:30' })
async function load() { rows.value = await listCanteens() }
function edit(row?: Canteen) { Object.assign(form, row || { id: undefined, name: '', address: '', status: 1, sort: 0, openTime: '06:30', closeTime: '20:30' }); dialog.value = true }
async function save() { if (!form.name.trim()) return ElMessage.warning('请填写食堂名称'); await saveCanteen(form); ElMessage.success('已保存'); dialog.value = false; await load() }
async function toggle(row: Canteen) { await saveCanteen({ ...row, status: row.status ? 0 : 1 }); await load() }
onMounted(load)
</script>
<template><div class="page-card"><div class="page-header"><div><h2 class="page-title">食堂管理</h2><p class="page-subtitle">先建立食堂，再配置档口和取餐时段。</p></div></div><div class="page-actionbar"><div class="query-area"><el-select v-model="statusFilter" placeholder="全部状态" clearable style="width:130px"><el-option label="启用" :value="1" /><el-option label="停用" :value="0" /></el-select><span class="muted">共 {{ filteredRows.length }} 个食堂</span></div><div class="action-area"><el-button type="primary" @click="edit()">新增食堂</el-button></div></div><el-table :data="filteredRows" stripe><el-table-column prop="id" label="ID" width="80" /><el-table-column prop="name" label="食堂" /><el-table-column prop="address" label="位置" /><el-table-column label="营业时间" width="180"><template #default="{ row }">{{ row.openTime }} - {{ row.closeTime }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag :type="row.status ? 'success' : 'info'">{{ row.status ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" align="center" header-align="center" class-name="action-column" width="160"><template #default="{ row }"><el-button text type="primary" @click="edit(row)">编辑</el-button><el-button text @click="toggle(row)">{{ row.status ? '停用' : '启用' }}</el-button></template></el-table-column></el-table>
<el-dialog v-model="dialog" :title="form.id ? '编辑食堂' : '新增食堂'" width="480px"><el-form label-position="top"><el-form-item label="食堂名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="位置"><el-input v-model="form.address" /></el-form-item><el-row :gutter="12"><el-col :span="12"><el-form-item label="开门时间"><el-input v-model="form.openTime" placeholder="06:30" /></el-form-item></el-col><el-col :span="12"><el-form-item label="关门时间"><el-input v-model="form.closeTime" placeholder="20:30" /></el-form-item></el-col></el-row><el-form-item label="排序"><el-input-number v-model="form.sort" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
